import unittest
import math
from candidate import truncate_number


class TestTruncateNumber(unittest.TestCase):
    def test_positive_integer_input_returns_zero(self):
        self.assertEqual(truncate_number(5), 0.0)

    def test_positive_float_with_fraction_returns_fraction(self):
        self.assertEqual(truncate_number(3.5), 0.5)

    def test_positive_float_with_large_fraction_returns_fraction(self):
        self.assertEqual(truncate_number(12345.6789), 0.6789)

    def test_float_boundary_integer_returns_zero(self):
        self.assertEqual(truncate_number(10.0), 0.0)

    def test_float_with_small_fraction_returns_small_fraction(self):
        self.assertAlmostEqual(truncate_number(0.000000001), 0.000000001, places=9)

    def test_large_float_input_returns_fraction(self):
        large = 1e308
        # 1e308 is not an integer; the fractional part should be zero
        self.assertEqual(truncate_number(large), 0.0)

    def test_negative_float_returns_positive_fraction(self):
        self.assertEqual(truncate_number(-3.7), 0.3)

    def test_negative_integer_returns_zero(self):
        self.assertEqual(truncate_number(-8), 0.0)

    def test_zero_input_returns_zero(self):
        self.assertEqual(truncate_number(0), 0.0)

    def test_nan_input_returns_nan(self):
        result = truncate_number(float('nan'))
        self.assertTrue(math.isnan(result))

    def test_infinite_input_returns_nan(self):
        result = truncate_number(float('inf'))
        self.assertTrue(math.isnan(result))

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            truncate_number(None)

    def test_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            truncate_number("1.5")

    def test_complex_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            truncate_number(1 + 2j)

    def test_boolean_input_returns_zero(self):
        self.assertEqual(truncate_number(True), 0.0)
        self.assertEqual(truncate_number(False), 0.0)

    def test_repeated_calls_consistency(self):
        num = 4.123456
        first = truncate_number(num)
        second = truncate_number(num)
        self.assertEqual(first, second)

    def test_fractional_part_with_rounding_error(self):
        num = 1.9999999999999999
        self.assertAlmostEqual(truncate_number(num), 0.9999999999999999, places=15)

    def test_decimal_like_input_as_float(self):
        num = float('1.2000000000000002')
        self.assertAlmostEqual(truncate_number(num), 0.20000000000000018, places=15)


if __name__ == "__main__":
    unittest.main()
